create table if not exists schools(id text primary key,name text not null);create table if not exists academic_years(id text primary key,school_id text not null,name text not null);create table if not exists schedule_versions(id text primary key,academic_year_id text not null,status text not null,created_at text not null);create table if not exists schedule_entries(id text primary key,schedule_version_id text not null,slot_id text not null,class_name text not null,subject_name text not null,teacher_name text not null,room_name text not null);create table if not exists history_events(id text primary key,entity_type text not null,entity_id text not null,event_type text not null,payload_json text,created_at text not null);